// Wall, floor, ceiling and sprite textures, generated by code at startup
// rather than loaded from image files (a page opened straight from disk isn't
// allowed to read the pixels of image files, so this keeps "just open
// index.html" working).
//
// A texture is a TEX_SIZE x TEX_SIZE grid of colours stored exactly like the
// screen buffer: one flat array, row after row, 4 bytes per texel (R, G, B, A).
// A "texel" is just a pixel of a texture. Walls are fully opaque; sprites use
// alpha 0 for the see-through parts around the object. Glass is the one
// thing with alpha in between: 0 = clear, 255 = solid, and e.g. 60 = a faint tint.
//
// THE LOOK: an 1980s mech hangar. Riveted steel, hazard stripes, rust, pipes,
// banks of green-screen computers, sodium-orange work lights. Anything that
// gives off light (screens, lamps, a robot's visor) is marked as glowing.

const TEX_SIZE = 64;

// Build a texture by asking colourAt(x, y) for the colour of every texel.
// colourAt returns [r, g, b], or null for a transparent texel, or
// [r, g, b, true] for a GLOWING texel: one that gives off its own light, so
// the renderer skips the fog (and the wall side-shading) for it, or
// [r, g, b, alpha] (see seeThrough) for a partly see-through texel.
// `colour` is the texture's main colour, used by the debug map.
function makeTexture(colour, colourAt) {
  // Uint8ClampedArray clamps out-of-range values to 0..255, so brightening a
  // colour past 255 saturates to white instead of wrapping round to dark.
  const pixels = new Uint8ClampedArray(TEX_SIZE * TEX_SIZE * 4);
  const glow = new Uint8Array(TEX_SIZE * TEX_SIZE); // 1 = glowing texel
  for (let y = 0; y < TEX_SIZE; y++) {
    for (let x = 0; x < TEX_SIZE; x++) {
      const rgb = colourAt(x, y);
      if (rgb === null) continue; // the array starts as all zeros: alpha 0, transparent
      const i = (y * TEX_SIZE + x) * 4;
      pixels[i] = rgb[0];
      pixels[i + 1] = rgb[1];
      pixels[i + 2] = rgb[2];
      pixels[i + 3] = typeof rgb[3] === 'number' ? rgb[3] : 255;
      if (rgb[3] === true) glow[y * TEX_SIZE + x] = 1;
    }
  }
  return { pixels, glow, colour };
}

function isTransparent(tex, texX, texY) {
  return tex.pixels[(texY * TEX_SIZE + texX) * 4 + 3] === 0;
}

// A repeatable "random" number in [0, 1): the same (x, y, seed) always gives
// the same answer, so the walls look identical every time you load the page.
// (Math.random would work too, but the textures would change on each reload.)
function noise(x, y, seed) {
  let h = (Math.imul(x, 374761393) + Math.imul(y, 668265263) + Math.imul(seed, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

function brighten(colour, f) {
  return [colour[0] * f, colour[1] * f, colour[2] * f];
}

// Blend from colour a towards colour b: t = 0 gives a, t = 1 gives b.
function mix(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function glowing(rgb) {
  return [rgb[0], rgb[1], rgb[2], true];
}

// A partly see-through texel: alpha 0 (invisible) to 255 (solid).
function seeThrough(rgb, alpha) {
  return [rgb[0], rgb[1], rgb[2], alpha];
}

// Fake roundness for anything cylindrical. u runs from -1 at the object's left
// edge to +1 at its right edge; brightness peaks a little left of centre, as if
// lit from the upper left.
function roundShade(u) {
  return 1.1 - 0.6 * Math.abs(u + 0.25);
}

// Diagonal yellow/black hazard stripes, 4 texels wide. `flip` slopes them the
// other way. (x + y) & 15 is (x + y) mod 16, and it works for negative numbers too.
function hazard(x, y, flip) {
  return (((flip ? x - y : x + y) & 15) < 8) ? HAZARD_YELLOW : HAZARD_BLACK;
}

// How far is point (px, py) from the line segment (x1, y1)-(x2, y2)? Used to
// draw the robot's angled legs as thick lines.
function segmentDistance(px, py, x1, y1, x2, y2) {
  const sx = x2 - x1;
  const sy = y2 - y1;
  // How far along the segment the nearest point is, 0 to 1.
  const t = Math.max(0, Math.min(1, ((px - x1) * sx + (py - y1) * sy) / (sx * sx + sy * sy)));
  return Math.hypot(px - (x1 + sx * t), py - (y1 + sy * t));
}

const STEEL = [88, 96, 108];
const DARK_STEEL = [40, 44, 52];
const RUST = [128, 72, 36];
const HAZARD_YELLOW = [220, 180, 30];
const HAZARD_BLACK = [30, 28, 26];
const SODIUM = [255, 170, 60];
const PHOSPHOR = [90, 240, 120];
const AMBER = [255, 176, 40];

// Keycard colours. A locked door (a level's lockedDoors) names one of these.
const KEY_COLOURS = { red: [220, 40, 40], blue: [60, 110, 255] };

// WALLS ---------------------------------------------------------------------

// Riveted steel plates, 32x32, with rust streaking down from the seams.
function makeSteelPlates() {
  const isRivet = (px, py) =>
    ((px === 5 || px === 28) && py % 6 === 5) || ((py === 5 || py === 28) && px % 6 === 5);
  return makeTexture(STEEL, (x, y) => {
    const px = x % 32; // position within this plate
    const py = y % 32;
    if (px < 2 || py < 2) return brighten(STEEL, 0.4);           // seam between plates
    if (isRivet(px, py)) return brighten(STEEL, 1.45);            // rivet head...
    if (isRivet(px - 1, py - 1)) return brighten(STEEL, 0.55);    // ...and its shadow
    let f = (0.85 + 0.2 * noise(Math.floor(x / 32), Math.floor(y / 32), 20)) * (0.9 + 0.12 * noise(x, y, 23));
    if (px === 2 || py === 2) f *= 1.25; // lit top/left edge of the plate
    if (px === 31 || py === 31) f *= 0.7;
    // Rust runs down some columns, getting heavier towards the bottom of each plate.
    const streak = noise(x, 0, 21) > 0.72 ? (py / 32) * (0.4 + 0.6 * noise(x, y >> 2, 22)) : 0;
    return mix(brighten(STEEL, f), RUST, streak * 0.75);
  });
}

// A bulkhead: hazard chevrons top and bottom, a vent grille, an amber warning lamp.
function makeBulkhead() {
  return makeTexture(HAZARD_YELLOW, (x, y) => {
    if (y === 12 || y === 51) return DARK_STEEL;
    if (y < 12) return hazard(x, y, false);
    if (y > 51) return hazard(x, y, true); // sloping the other way: a chevron
    const lamp = Math.hypot(x + 0.5 - 8, y + 0.5 - 32);
    if (lamp < 2) return glowing([255, 230, 150]);
    if (lamp < 3.5) return glowing(AMBER);
    if (lamp < 4.5) return DARK_STEEL;
    if (x >= 18 && x < 56 && y >= 18 && y < 46) {         // the vent
      if (x === 18 || y === 18) return brighten(STEEL, 0.5);
      if (x === 55 || y === 45) return brighten(STEEL, 1.2);
      return (x % 4 === 0) ? brighten(STEEL, 0.25) : brighten(STEEL, 0.75 + 0.1 * noise(x, y, 24));
    }
    return brighten([70, 76, 86], 0.9 + 0.15 * noise(x, y, 25));
  });
}

// A bank of computers: two rows of green screens with scrolling text, and a
// strip of blinking lights. `frame` (0-3) changes the text and the lights, so
// showing the frames in turn animates it (wallTexture, below).
function makeComputerBank(frame) {
  return makeTexture(PHOSPHOR, (x, y) => {
    const screenCol = x < 32 ? 0 : 1;
    const sx = x - (screenCol === 0 ? 4 : 35); // position within a screen
    const screenRow = y < 30 ? 0 : 1;
    const sy = y - (screenRow === 0 ? 5 : 35);
    if (sx >= 0 && sx < 25 && sy >= 0 && sy < 19) {
      if (sx === 0 || sy === 0 || sx === 24 || sy === 18) return brighten(STEEL, 0.75); // bezel
      // Lines of "text": one every 3 rows, each a run of on/off blocks whose
      // length and pattern depend on the frame, so the text seems to scroll.
      const line = Math.floor((sy - 2) / 3);
      const id = screenRow * 2 + screenCol;
      if ((sy - 2) % 3 === 0 && sy >= 2 && sx >= 2) {
        const length = 4 + Math.floor(noise(id, line + frame, 26) * 18);
        if (sx - 2 < length && noise(sx >> 1, line + frame * 7, 27 + id) > 0.25) return glowing(PHOSPHOR);
      }
      return [10, 28, 16]; // dark screen
    }
    if (y >= 28 && y < 30 && x % 4 === 1) {
      // Indicator lights: each one on or off, amber or green, re-rolled every frame.
      const n = noise(x, frame, 28);
      if (n > 0.55) return glowing(n > 0.8 ? AMBER : PHOSPHOR);
      return [30, 24, 18];
    }
    if (y >= 57 && x % 8 < 6 && x > 2) return brighten(DARK_STEEL, y === 57 ? 1.6 : 1.1); // drawer handles
    return brighten(DARK_STEEL, 0.9 + 0.15 * noise(x, y, 29));
  });
}

// A wall of vertical pipes of different widths and metals, with brackets and a valve.
function makePipes() {
  const pipes = [
    { from: 2, to: 12, colour: STEEL },
    { from: 14, to: 20, colour: [160, 92, 52] },   // copper
    { from: 23, to: 40, colour: [96, 100, 104] },  // the big one, with the valve
    { from: 43, to: 49, colour: RUST },
    { from: 52, to: 62, colour: [92, 100, 72] },   // olive paint
  ];
  return makeTexture(STEEL, (x, y) => {
    // The valve wheel on the big pipe: a red ring with four spokes.
    const vx = x + 0.5 - 31.5;
    const vy = y + 0.5 - 22;
    const vr = Math.hypot(vx, vy);
    if (vr >= 5 && vr < 7) return [170, 40, 30];
    if (vr < 5 && (Math.abs(vx) < 1 || Math.abs(vy) < 1)) return [140, 32, 24];
    if ((y >= 4 && y < 8) || (y >= 44 && y < 48)) {                // brackets across the pipes
      return brighten(DARK_STEEL, y === 4 || y === 44 ? 1.5 : 1.0);
    }
    for (const p of pipes) {
      if (x < p.from || x >= p.to) continue;
      const halfW = (p.to - p.from) / 2;
      const u = (x + 0.5 - p.from - halfW) / halfW;
      return brighten(p.colour, roundShade(u) * (0.9 + 0.15 * noise(x, y, 30)));
    }
    return [22, 22, 26]; // the dark gap behind the pipes
  });
}

// A blast door: steel with ribs, hazard chevrons along its leading (left)
// edge, and a status light. As before, the leading edge is the one that
// moves as the door slides open (see hitDoor in raycaster.js).
// `lock` is null for an ordinary door (green light), or a key colour: then
// the light shows that colour and a stripe of it is painted across the door,
// so you can tell from a distance which keycard it wants.
function makeBlastDoor(lock) {
  const band = lock ? KEY_COLOURS[lock] : null;
  return makeTexture([84, 90, 98], (x, y) => {
    if (x < 10) return hazard(x, y, false);
    if (x === 10 || x >= 62 || y < 2 || y >= 62) return DARK_STEEL;
    const light = Math.hypot(x + 0.5 - 16, y + 0.5 - 32);
    if (light < 2) return glowing(band ? brighten(band, 1.3) : [80, 255, 120]);
    if (light < 3) return DARK_STEEL;
    if (band && y >= 40 && y < 47 && x > 22) return brighten(band, 0.85 + 0.15 * noise(x, y, 56)); // painted stripe
    const rib = y % 12;
    if (rib === 0) return brighten([84, 90, 98], 1.35);
    if (rib === 1) return brighten([84, 90, 98], 0.5);
    return brighten([84, 90, 98], 0.9 + 0.12 * noise(x, y, 31));
  });
}

// SEE-THROUGH PANELS (panels.js) ----------------------------------------------
// Both sit in a steel frame round the cell's edge, so a window several cells
// long shows a mullion between each pane.

function panelFrame(x, y) {
  if (x < 2 || x >= 62 || y < 3 || y >= 61) {
    const bolt = (y === 1 || y === 62) && x % 8 === 4;
    return brighten(DARK_STEEL, bolt ? 2.2 : 1 + 0.25 * noise(x, y, 70));
  }
  return null; // inside the frame
}

// Wired safety glass, as fitted to factory windows: a faint blue-green tint,
// a diamond mesh of wire set into it, two diagonal glints, and grime
// gathering towards the bottom. Its alpha is how much it hides: 0 would be
// perfectly clear glass, 255 a painted-over window.
//   state 'intact'    as fitted
//   state 'cracked'   one hit taken: cracks radiate from where it struck
//   state 'shattered' only jagged teeth left round the frame; the hole is clear
function makeGlass(state) {
  const tint = [150, 200, 215];
  const impactX = 38, impactY = 27; // where the first hit landed, for the cracks
  return makeTexture(tint, (x, y) => {
    const frame = panelFrame(x, y);
    if (frame) return frame;

    if (state === 'shattered') {
      // Triangular teeth along each inside edge of the frame. For each edge:
      // how far in from it this texel is, against how tall the tooth is at
      // this point along it (a triangle wave, its height varied by noise).
      const tooth = (along, seed) => {
        const seg = Math.floor(along / 9);
        const t = Math.abs((along % 9) - 4.5) / 4.5; // 0 at a tooth's tip, 1 between teeth
        return (2 + 9 * noise(seg, seed, 71)) * (1 - t);
      };
      const inTooth = (x - 2) < tooth(y, 1) || (61 - x) < tooth(y, 2) ||
                      (y - 3) < tooth(x, 3) || (60 - y) < tooth(x, 4);
      if (!inTooth) return null; // the hole: nothing left in it at all
      return seeThrough(brighten(tint, 1.3), 120); // broken edges catch the light
    }

    if (state === 'cracked') {
      // Cracks: seven lines out from the impact point, each a random length.
      // A texel is on spoke k if the angle between it and the spoke, times
      // its distance out, is under 0.7 texels: i.e. it's within 0.7 texels
      // of the spoke's line. A gentle sine wobble keeps them from looking ruled.
      const dx = x - impactX, dy = y - impactY;
      const r = Math.hypot(dx, dy);
      for (let k = 0; k < 7; k++) {
        const spoke = k * 2 * Math.PI / 7 + 0.6 * noise(k, 0, 72) + 0.08 * Math.sin(r * 0.5 + k);
        const d = Math.atan2(dy, dx) - spoke;
        const off = Math.abs(Math.atan2(Math.sin(d), Math.cos(d))) * r; // wrapped into -PI..PI first
        if (off < 0.7 && r < 10 + 26 * noise(k, 1, 72)) return seeThrough([235, 245, 250], 210);
      }
      if (r < 3 || Math.abs(r - 7) < 0.6) return seeThrough([235, 245, 250], 210); // the impact itself
    }

    // The wire mesh: diagonal lines every 12 texels, both ways.
    if ((x + y) % 12 === 0 || (((x - y) % 12) + 12) % 12 === 0) return seeThrough([60, 66, 70], 190);
    // Glints: two thin diagonal bands of reflected light.
    const g = (x + y * 0.6) % 48;
    if ((g > 6 && g < 9) || (g > 11 && g < 12.5)) return seeThrough([230, 245, 250], 110);
    // Grime: more of it lower down, where hands and dirt reach.
    const grime = Math.max(0, (y - 38) / 23) * (0.6 + 0.4 * noise(x >> 1, y >> 1, 73));
    return seeThrough(mix(tint, [70, 60, 45], grime), 55 + 90 * grime);
  });
}

// A steel bar grille: thick round bars with two flat cross-bars. Everything
// between them has alpha 0, so you (and bullets, and robots' eyes) see and
// shoot straight through the gaps.
function makeGrate() {
  const steel = [96, 98, 92];
  return makeTexture(steel, (x, y) => {
    const frame = panelFrame(x, y);
    if (frame) return frame;
    const rust = noise(x >> 1, y >> 2, 74) < 0.15 ? 0.75 : 1;
    if (Math.abs(y - 22) < 2 || Math.abs(y - 42) < 2) {
      return mix(brighten(steel, y % 2 === 0 ? 1.15 : 0.8), RUST, rust < 1 ? 0.5 : 0); // flat bar
    }
    const bx = (x - 2) % 8; // position across one bar plus gap, 0..7
    if (bx >= 2 && bx < 5) {
      return mix(brighten(steel, roundShade((bx - 3) / 1.5)), RUST, rust < 1 ? 0.4 : 0); // round bar
    }
    return null;
  });
}

// Glass bursting: a cloud of glinting fragments, falling and spreading out
// as `frame` goes from 0 to 3. Drawn as an effect sprite where the pane was.
function makeGlassBurst(frame) {
  return makeTexture([200, 230, 240], (x, y) => {
    for (let n = 0; n < 40; n++) {
      // Each fragment starts near the middle and falls, faster the later the frame.
      const sx = 32 + (noise(n, 0, 75) - 0.5) * (20 + frame * 14);
      const sy = 30 + (noise(n, 1, 75) - 0.5) * 28 + frame * frame * 4;
      if (Math.abs(x - sx) < 1 && Math.abs(y - sy) < 1 + (n % 3 === 0 ? 1 : 0)) {
        return noise(n, 2, 75) < 0.4 ? glowing([235, 250, 255]) : [150, 200, 215];
      }
    }
    return null;
  });
}

// STEAM (steam.js) -----------------------------------------------------------

// Smooth noise: noise() on a coarse grid of `cell`-texel squares, blended
// between grid points (bilinear, as in lightAt), so it gives soft blobs
// instead of speckle. It repeats every `wrapY` texels vertically, so a steam
// animation that scrolls upward by exactly wrapY loops without a seam.
function smoothNoise(x, y, cell, wrapY, seed) {
  const gx = x / cell, gy = y / cell;
  const x0 = Math.floor(gx), y0 = Math.floor(gy);
  const fx = gx - x0, fy = gy - y0;
  const rows = wrapY / cell;
  const at = (ix, iy) => noise(ix, ((iy % rows) + rows) % rows, seed);
  const top = at(x0, y0) + (at(x0 + 1, y0) - at(x0, y0)) * fx;
  const bottom = at(x0, y0 + 1) + (at(x0 + 1, y0 + 1) - at(x0, y0 + 1)) * fx;
  return top + (bottom - top) * fy;
}

const STEAM_FRAMES = 6;
const STEAM_LOOP = 48; // texels the billows rise over a whole cycle of frames

// A plume of steam: a soft, wavering column, narrow where it leaves the vent
// at the floor and spreading as it rises, made of billows that drift upwards
// from frame to frame. Its alpha is how thick the steam is: you see the room
// through it. `sputter` gives the weak, low puffs that warn of a burst.
// `gas`: the lab's vents blow a sickly green toxic gas instead (steam.js).
function makeSteam(frame, sputter, gas) {
  const rise = frame * STEAM_LOOP / STEAM_FRAMES;
  const tint = gas ? [150, 205, 110] : [200, 205, 212];
  return makeTexture([210, 214, 220], (x, y) => {
    const up = (63 - y) / 63; // 0 at the floor, 1 at the ceiling
    if (sputter && up > 0.4) return null;
    const half = 5 + 22 * Math.sqrt(up);
    const across = Math.abs(x + 0.5 - 32 - 3 * Math.sin(up * 6 + frame * 2 * Math.PI / STEAM_FRAMES)) / half;
    if (across >= 1) return null;
    const n = 0.6 * smoothNoise(x, y + rise, 8, STEAM_LOOP, 120) + 0.4 * smoothNoise(x, y + rise * 2, 4, STEAM_LOOP, 121);
    // A sputter's puffs thin out to nothing by 40% of the way up, rather than stopping in a hard edge.
    const density = (1 - across * across) * (0.3 + 0.7 * n) * (1 - 0.4 * up) * (sputter ? 0.7 * (1 - up / 0.4) : 1);
    if (density < 0.12) return null;
    return seeThrough(brighten(tint, 0.85 + 0.3 * n), Math.min(gas ? 170 : 210, 240 * density));
  });
}

// FLOOR AND CEILING -----------------------------------------------------------

// Diamond-plate steel: a lattice of small raised diamonds, with oil stains.
function makeDiamondPlate() {
  const base = [84, 88, 96];
  return makeTexture(base, (x, y) => {
    if (x === 0 || y === 0) return brighten(base, 0.45); // seam at the cell edge
    const lx = (x + (Math.floor(y / 8) % 2) * 4) % 8; // every other row of diamonds shifted
    const ly = y % 8;
    let f = 0.85 + 0.12 * noise(x, y, 32);
    if (Math.abs(lx - 3.5) + Math.abs(ly - 3.5) < 2.5) f = lx + ly < 7 ? 1.25 : 0.7; // lit top-left, shaded bottom-right
    if (noise(x >> 3, y >> 3, 33) < 0.12) f *= 0.7; // oil stain
    return brighten(base, f);
  });
}

// Ceiling: steel girders along the cell edges, dark between them, and a strip
// light fitting in the middle of every cell. `tube` is the colour the strip
// glows, or null for a dead one. The renderer picks a version per cell: lit
// only in CEILING_LIGHTS cells, and red while that area's alarm is going.
function makeGirders(tube) {
  const beam = [70, 72, 80];
  return makeTexture(beam, (x, y) => {
    if (x >= 14 && x < 50 && y >= 29 && y < 35) {
      if (x === 14 || x === 49 || y === 29 || y === 34) return [50, 50, 56]; // light housing
      return tube ? glowing(tube) : [62, 60, 58];                            // tube: on, or dead
    }
    const ex = Math.min(x, 63 - x); // distance from the nearest vertical edge
    const ey = Math.min(y, 63 - y);
    if (ex < 6 || ey < 6) {
      const e = Math.min(ex, ey);
      if (e === 0 || e === 5) return brighten(beam, 0.6);      // flange edges
      if (e === 2 && (x + y) % 6 === 0) return brighten(beam, 1.5); // rivets
      return brighten(beam, 0.95 + 0.1 * noise(x, y, 34));
    }
    return brighten([26, 26, 32], 0.9 + 0.2 * noise(x, y, 35));
  });
}

// OBJECTS (sprites) -------------------------------------------------------------
// A sprite is drawn the same size as a wall cell (1 unit tall, floor to
// ceiling), so where the object sits in its 64x64 square decides where it
// appears in the world: a drum drawn in the bottom half stands on the floor,
// a lamp drawn at the top hangs from the ceiling.

// A red fuel drum with a hazard label.
function makeDrum() {
  const paint = [170, 64, 36];
  return makeTexture(paint, (x, y) => {
    if (y < 24) return null;
    const dx = x + 0.5 - 32;
    if (Math.abs(dx) > 12) return null;
    const round = roundShade(dx / 12);
    if (y <= 25) return brighten([120, 120, 128], round * 1.2);       // rim
    if (y === 34 || y === 35 || y === 52 || y === 53) return brighten(paint, round * 0.6); // ribs
    const label = Math.abs(dx) + Math.abs(y + 0.5 - 43.5);           // a diamond-shaped label
    if (label < 6) return brighten(HAZARD_YELLOW, round);
    if (label < 7.2) return HAZARD_BLACK;
    return brighten(paint, round * (0.88 + 0.15 * noise(x, y, 36)));
  });
}

// What's left of a drum after it explodes: the bottom of the shell, torn open
// with a ragged top edge, blackened, with a few embers still glowing.
function makeDrumWreck() {
  return makeTexture([60, 30, 22], (x, y) => {
    const dx = x + 0.5 - 32;
    if (Math.abs(dx) > 12) return null;
    const top = 48 + Math.floor(noise(x >> 1, 0, 47) * 8); // ragged, torn edge
    if (y < top) return null;
    if (y < top + 2) return [24, 20, 18];                   // the torn lip, seen from inside
    if (noise(x, y, 48) > 0.96) return glowing(SODIUM);     // embers
    const soot = 0.45 + 0.4 * noise(x >> 1, y >> 1, 49);
    return brighten([150, 60, 36], roundShade(dx / 12) * soot);
  });
}

// The fireball when a drum goes up, as frames shown one after another.
// Each frame is a ragged ball: a white-hot core, orange fire, a red edge.
// As it ages it grows, and more of it turns from fire to dark smoke. The
// fire is glowing, so neither fog nor the light map dims it.
function makeFireball(frame) {
  const radius = [9, 15, 19, 21, 22][frame];
  const heat = [1, 1, 0.75, 0.45, 0.15][frame]; // how much of the ball is still fire, not smoke
  return makeTexture(SODIUM, (x, y) => {
    // Distance from the centre, roughened by noise so the edge isn't a perfect circle.
    const d = Math.hypot(x + 0.5 - 32, y + 0.5 - 42) + 5 * noise(x >> 1, y >> 1, 50 + frame);
    if (d > radius) return null;
    const t = d / radius; // 0 at the centre, 1 at the edge
    if (t < heat * 0.45) return glowing([255, 245, 200]);
    if (t < heat * 0.75) return glowing([255, 170, 50]);
    if (t < heat) return glowing([220, 70, 20]);
    return brighten([70, 64, 58], 0.8 + 0.4 * noise(x, y, 55)); // smoke
  });
}

// A hydraulic support strut, floor to ceiling: a painted housing at the top,
// a chrome piston, and a hazard-striped foot.
function makeStrut() {
  return makeTexture([190, 160, 40], (x, y) => {
    const dx = x + 0.5 - 32;
    if (y < 18) {
      if (Math.abs(dx) > 11) return null;
      if (y === 17 || (y % 6 === 3 && Math.abs(Math.abs(dx) - 8) < 1)) return DARK_STEEL; // edge and bolts
      return brighten([190, 160, 40], roundShade(dx / 11));
    }
    if (y < 50) {
      if (Math.abs(dx) > 4) return null;
      const u = dx / 4;
      if (Math.abs(u + 0.45) < 0.2) return [235, 238, 245];           // chrome highlight
      return brighten([150, 156, 168], roundShade(u) * 0.95);
    }
    if (Math.abs(dx) > 14) return null;
    if (y === 50) return DARK_STEEL;
    return brighten(hazard(x, y, false), roundShade(dx / 14));
  });
}

// A caged sodium work lamp hanging from the ceiling.
function makeCagedLamp() {
  return makeTexture(SODIUM, (x, y) => {
    const dx = x + 0.5 - 32;
    if (y < 4) return Math.abs(dx) < 2 ? DARK_STEEL : null;            // bracket
    if (y < 8) return Math.abs(dx) < 6 ? brighten(STEEL, 0.8) : null;  // housing
    if (y < 23) {
      if (Math.abs(dx) > 7) return null;
      if (x % 3 === 0 || y === 14 || y === 22) return [50, 50, 56];    // the cage's bars
      const d = Math.hypot(dx, y + 0.5 - 15);
      if (d < 2.5) return glowing([255, 230, 150]);                    // bulb core
      if (d < 5) return glowing(SODIUM);
      return glowing([200, 110, 40]);                                  // glow filling the cage
    }
    return null;
  });
}

// SHAPES -----------------------------------------------------------------------
// The robots and creatures (robot-art.js, creature-art.js) are drawn as
// SHAPES: functions (x, y) -> colour or null, like the colourAt that
// makeTexture takes. Keeping shapes separate from textures lets them be
// mirrored or resized before they're baked into a texture.

// A shape drawn at a different size, feet still on the floor: each texel asks
// the full-size shape about the point it corresponds to, scaling around the
// bottom middle of the texture.
function scaledShape(shape, scale) {
  if (scale === 1) return shape;
  return (x, y) => {
    const sx = Math.floor(32 + (x + 0.5 - 32) / scale);
    const sy = Math.floor(TEX_SIZE - (TEX_SIZE - (y + 0.5)) / scale);
    if (sx < 0 || sx >= TEX_SIZE || sy < 0 || sy >= TEX_SIZE) return null;
    return shape(sx, sy);
  };
}

// A shape flipped left to right (reading x backwards), if `mirror` is true.
function mirroredShape(shape, mirror) {
  return mirror ? (x, y) => shape(TEX_SIZE - 1 - x, y) : shape;
}

// SECURITY -------------------------------------------------------------------
// A security camera on a pole, head at eye height so you can shoot it.
// state: 'watching' (red lens and status light), 'offline' (switched off at a
// terminal), 'destroyed' (head shot away, sparking).
function makeCamera(state) {
  return makeTexture([60, 62, 70], (x, y) => {
    const dx = x + 0.5 - 32;
    const adx = Math.abs(dx);
    if (y >= 60) return adx < 5 ? brighten(DARK_STEEL, 1.3) : null;                 // base
    if (y >= 36) return adx < 1.5 ? brighten(DARK_STEEL, 1.2) : null;               // pole
    if (state === 'destroyed') {
      if (y < 31 || adx >= 6) return null;
      if (noise(x, y, 60) > 0.85) return glowing(SODIUM);                          // sparks
      return y < 33 && noise(x, 0, 61) > 0.5 ? null : brighten([60, 62, 70], 0.5); // torn stump
    }
    if (y < 24 || adx >= 7) return null;
    const lens = Math.hypot(dx, y + 0.5 - 30);
    if (lens < 2) return state === 'watching' ? glowing([255, 160, 140]) : [30, 40, 32];
    if (lens < 3.2) return state === 'watching' ? glowing([255, 40, 30]) : [20, 26, 22];
    if (lens < 4) return [16, 16, 18];
    if (dx > 3 && dx < 5 && y >= 25 && y < 27) return state === 'watching' ? glowing(AMBER) : DARK_STEEL; // status light
    return brighten([60, 62, 70], 0.9 + 0.2 * (y < 26 ? 1 : 0));
  });
}

// One short piece of a tripwire's laser beam, at knee height. A beam is drawn
// as a row of these, a quarter of a cell apart (security.js).
function makeBeam() {
  return makeTexture([255, 40, 30], (x, y) => {
    if (y < 44 || y > 45 || Math.abs(x + 0.5 - 32) > 8) return null;
    return glowing(y === 44 ? [255, 120, 100] : [255, 40, 30]);
  });
}

// A security terminal set into a wall: a screen and a keypad. Red text while
// it's armed; green once you've shut the area's security down.
function makeTerminal(safe) {
  const text = safe ? [90, 240, 120] : [255, 60, 40];
  return makeTexture(STEEL, (x, y) => {
    if (x >= 14 && x < 50 && y >= 12 && y < 34) {
      if (x === 14 || y === 12 || x === 49 || y === 33) return brighten(STEEL, 0.6); // bezel
      const line = Math.floor((y - 15) / 3);
      if ((y - 15) % 3 === 0 && y >= 15 && x >= 17 && x - 17 < 8 + Math.floor(noise(line, safe ? 1 : 0, 62) * 22)) {
        return glowing(text);
      }
      return glowing(brighten(text, 0.12));                                     // screen glow
    }
    if (x >= 20 && x < 44 && y >= 38 && y < 52) {
      return (x - 20) % 6 < 4 && (y - 38) % 5 < 3 ? brighten(STEEL, 1.4) : brighten(DARK_STEEL, 1.1); // keypad
    }
    if (x < 2 || y < 2 || x >= 62 || y >= 62) return brighten(STEEL, 0.4);
    return brighten(STEEL, 0.85 + 0.12 * noise(x, y, 63));
  });
}

// THE SECURITY CORE (core.js): a wall of server racks with a red "heart" in
// the middle that pulses. `damage` 0, 1 or 2 adds sparking cracks and
// scorch; `pulse` 0-3 is how bright the heart is this moment (the core
// picks a frame from the time, faster as it weakens). `dead` draws the
// wreck: dark racks, a blown-out heart.
function makeCore(damage, pulse, dead) {
  const heartColour = [255, 40, 30];
  return makeTexture([70, 74, 80], (x, y) => {
    if (x < 2 || y < 2 || x >= 62 || y >= 62) return brighten(DARK_STEEL, 0.8); // frame
    const r = Math.hypot(x + 0.5 - 32, y + 0.5 - 30);
    if (r < 10) {                                                              // the heart and its housing
      if (dead) return r < 7 ? (noise(x, y, 121) < 0.5 ? [20, 16, 14] : [60, 30, 20]) : DARK_STEEL;
      if (r < 7) return glowing(brighten(heartColour, 0.45 + 0.18 * pulse + 0.3 * (1 - r / 7)));
      if (r < 8) return [20, 20, 24];
      return brighten(STEEL, 1.2);
    }
    // Racks: rows of drive bays, each with a tiny status light.
    const bay = (y - 2) % 6, col = Math.floor((x - 2) / 15);
    if (bay === 0) return [24, 24, 28];
    if (!dead && bay === 3 && (x - 2) % 15 === 12) {
      return glowing(noise(col, Math.floor((y - 2) / 6), 120 + pulse) < 0.6 ? [90, 255, 120] : [255, 180, 40]);
    }
    // Damage: dark cracks radiating from the heart, scorch around them.
    const a = Math.atan2(y + 0.5 - 30, x + 0.5 - 32);
    for (let k = 0; k < damage * 3 + (dead ? 4 : 0); k++) {
      const spoke = k * 2.4 + 0.5 * noise(k, 0, 122);
      const off = Math.abs(Math.atan2(Math.sin(a - spoke), Math.cos(a - spoke))) * r;
      if (off < 0.8 && r < 14 + 14 * noise(k, 1, 122)) return [14, 12, 12];
      if (off < 2.5 && r < 18) return brighten([70, 74, 80], 0.45);
    }
    if (dead) return brighten([70, 74, 80], 0.35 + 0.15 * noise(x, y, 123));
    return brighten([70, 74, 80], 0.85 + 0.15 * noise(x, y, 124));
  });
}

// THE EXIT LIFT (core.js): heavy doors with hazard chevrons, and a status
// lamp: red while the lift is locked, green once the core is down.
function makeLift(open) {
  const lamp = open ? [90, 255, 120] : [255, 50, 30];
  return makeTexture([96, 100, 90], (x, y) => {
    if (x < 3 || x >= 61 || y < 4 || y >= 62) return brighten(DARK_STEEL, 1.1);        // frame
    if (y < 12) {                                                                         // header with the lamp
      if (Math.hypot(x + 0.5 - 32, y + 0.5 - 8) < 3) return glowing(lamp);
      return brighten(STEEL, 0.9);
    }
    if (Math.abs(x + 0.5 - 32) < 1) return [18, 18, 20];                                // the seam between the doors
    if (y >= 50 && y < 58) return hazard(x, y, x < 32);                                   // chevrons at the foot
    if ((y - 12) % 9 === 0) return brighten([96, 100, 90], 0.6);                         // panel ribs
    return brighten([96, 100, 90], 0.9 + 0.1 * noise(x, y, 125));
  });
}

// THE LAB ------------------------------------------------------------------------
// Deeper in the complex: stained white tiles, steel benches, green biohazard
// markings, cold fluorescent panels. Levels with theme 'lab' use the lab's
// floor and ceiling (below); its walls are their own cells ('t', 'b').

const TILE_WHITE = [200, 204, 194];
const GROUT = [104, 108, 98];
const GRIME = [118, 100, 60];
const BIO_GREEN = [120, 220, 60];

// One texel of the lab's wall tiles, 16x16 each: glazed, chipped and
// cracked here and there, with grime running down from the grout and
// collecting towards the floor.
function labTileTexel(x, y) {
  const tx = x % 16, ty = y % 16; // position within this tile
  const tile = Math.floor(x / 16) + 4 * Math.floor(y / 16);
  if (tx === 0 || ty === 0) return brighten(GROUT, 0.85 + 0.25 * noise(x, y, 200));
  let c = brighten(TILE_WHITE, 0.9 + 0.08 * noise(tile, 0, 201) + 0.05 * noise(x, y, 202));
  if (tx === 1 || ty === 1) c = brighten(c, 1.08);   // glaze catching the light on the top/left edge
  if (tx === 15 || ty === 15) c = brighten(c, 0.84);
  // A crack across some tiles: a thin dark line corner to corner.
  if (noise(tile, 1, 205) < 0.18) {
    const flip = noise(tile, 2, 205) < 0.5;
    if (segmentDistance(tx + 0.5, ty + 0.5, flip ? 13 : 3, 2, flip ? 4 : 12, 14) < 0.6) return brighten(GROUT, 0.6);
  }
  // A chipped corner: the grey render behind shows through.
  if (noise(tile, 3, 206) < 0.12 && tx + ty < 6) return brighten(GROUT, 1.1 + 0.2 * noise(x, y, 207));
  const streak = noise(x, 0, 203) > 0.8 ? (y / 64) * noise(x, y >> 3, 204) : 0;
  return mix(c, GRIME, streak * 0.6 + 0.3 * (y / 64) * (y / 64));
}

function makeLabTiles() {
  return makeTexture(TILE_WHITE, labTileTexel);
}

// Is (x, y) on a biohazard symbol centred at (cx, cy)? Three round lobes,
// each with a hole bitten out of its outer side, round a small clear hub,
// and a ring through them. `s` scales it (1 = about 22 texels across).
function onBiohazard(x, y, cx, cy, s) {
  const px = (x + 0.5 - cx) / s, py = (y + 0.5 - cy) / s;
  const r = Math.hypot(px, py);
  if (r < 1.6) return false;                           // the hub's clear ring
  if (r < 2.6) return true;                            // the hub
  let onLobe = false;
  for (let k = 0; k < 3; k++) {
    const a = -Math.PI / 2 + k * 2 * Math.PI / 3;
    const ca = Math.cos(a), sa = Math.sin(a);
    if (Math.hypot(px - ca * 7, py - sa * 7) < 2.9) return false; // the bite out of a lobe (it breaks the ring too)
    if (Math.hypot(px - ca * 5.2, py - sa * 5.2) < 4.8) onLobe = true;
  }
  return onLobe || (r > 6.3 && r < 7.6);               // a lobe, or the ring through them
}

// Steel bench cabinets along the foot of a tiled wall, with a biohazard
// placard above the worktop.
function makeLabCabinet() {
  const top = [150, 156, 160], door = [92, 100, 104];
  return makeTexture(door, (x, y) => {
    if (y < 33) {
      if (x >= 22 && x < 42 && y >= 6 && y < 26) {     // the placard
        if (x === 22 || x === 41 || y === 6 || y === 25) return [30, 34, 30];
        if (onBiohazard(x, y, 32, 16, 0.85)) return [24, 30, 20];
        return brighten(BIO_GREEN, 0.9 + 0.12 * noise(x, y, 208));
      }
      return labTileTexel(x, y);
    }
    if (y < 36) return brighten(top, y === 33 ? 1.3 : 0.95 - 0.1 * (y - 34)); // the worktop's steel lip
    if (y === 36 || y >= 62) return [26, 28, 30];                              // shadow under the lip; kick plate
    const dx = x % 21;                                                          // three cabinet doors
    if (dx === 0) return [30, 32, 34];
    if (dx === 1) return brighten(door, 1.25);
    if (dx >= 15 && dx < 18 && y >= 42 && y < 50) return brighten(top, 1.2);    // handle
    return mix(brighten(door, 0.9 + 0.1 * noise(x, y, 209)), GRIME, 0.25 * ((y - 36) / 26));
  });
}

// The lab floor: big vinyl tiles, two to a cell each way, pale and grey in a
// chequer, scuffed, with grime in the seams.
function makeLabFloor() {
  const pale = [168, 174, 164], grey = [120, 126, 120];
  return makeTexture(pale, (x, y) => {
    if (x % 32 === 0 || y % 32 === 0) return brighten(GROUT, 0.7);
    const base = ((x >> 5) + (y >> 5)) % 2 === 0 ? pale : grey;
    let f = 0.9 + 0.08 * noise(x, y, 210) + 0.04 * noise(x >> 2, y >> 2, 211);
    if (noise(x >> 1, y >> 3, 212) < 0.04) f *= 0.8; // scuffs from trolley wheels
    return mix(brighten(base, f), GRIME, noise(x >> 3, y >> 3, 213) < 0.1 ? 0.3 : 0);
  });
}

// The lab ceiling: white panels on a T-bar grid, perforated, with a
// fluorescent fitting behind a diffuser grid in the middle of every cell.
// `tube` is its colour, or null when it's dead (as makeGirders).
function makeLabCeiling(tube) {
  const panel = [176, 180, 176], bar = [120, 124, 122];
  return makeTexture(panel, (x, y) => {
    if (x >= 12 && x < 52 && y >= 26 && y < 38) {
      if (x === 12 || x === 51 || y === 26 || y === 37) return [70, 74, 76];   // the fitting's frame
      if (!tube) return (x % 4 === 0 || y % 4 === 0) ? [58, 60, 62] : [96, 98, 100];
      return glowing((x % 4 === 0 || y % 4 === 0) ? brighten(tube, 0.75) : tube); // lit through the diffuser grid
    }
    if (x % 32 < 2 || y % 32 < 2) return brighten(bar, x % 32 === 0 || y % 32 === 0 ? 0.7 : 1); // T-bars
    if (x % 4 === 2 && y % 4 === 2) return brighten(panel, 0.6);                               // perforations
    return mix(brighten(panel, 0.9 + 0.1 * noise(x, y, 214)), GRIME, noise(x >> 4, y >> 4, 215) < 0.2 ? 0.25 : 0);
  });
}

// THE BREEDING CHAMBER (core.js, levels whose objective is 'chamber'): a
// steel bulkhead with a round viewport, packed behind it with something that
// grew: a red membrane threaded with veins, studded with glowing green eggs
// that pulse. Growth has crept out over the steel round the viewport.
// `damage` 0-2 cracks the glass and lets ooze run down; `pulse` 0-3 is how
// bright the eggs are this moment; `dead` is the burnt-out wreck.
const CHAMBER_EGGS = [[24, 22, 5], [38, 19, 6], [30, 34, 7], [43, 33, 5], [19, 36, 4.5], [34, 46, 4], [47, 23, 3.5], [22, 47, 3.5]];
const MEMBRANE = [110, 34, 50];
const EGG_GLOW = [150, 255, 90];

function makeChamber(damage, pulse, dead) {
  const cx = 32, cy = 30, port = 24;
  return makeTexture(MEMBRANE, (x, y) => {
    const r = Math.hypot(x + 0.5 - cx, y + 0.5 - cy);
    const a = Math.atan2(y + 0.5 - cy, x + 0.5 - cx);
    if (r < port) {
      // Cracks in the glass, from the centre outwards: more with damage.
      for (let k = 0; k < damage * 3; k++) {
        const spoke = k * 2.4 + 0.6 * noise(k, 0, 220);
        const off = Math.abs(Math.atan2(Math.sin(a - spoke), Math.cos(a - spoke))) * r;
        if (off < 0.6 && r > 3 && r < port * (0.5 + 0.5 * noise(k, 1, 220))) return [210, 240, 200];
      }
      for (const [ex, ey, er] of CHAMBER_EGGS) {
        const d = Math.hypot(x + 0.5 - ex, y + 0.5 - ey) / er;
        if (d >= 1) continue;
        if (dead) return d < 0.7 ? [16, 14, 10] : [60, 44, 30];                  // burst and charred
        if (d < 0.65) return glowing(brighten(EGG_GLOW, 0.4 + 0.15 * pulse + 0.35 * (1 - d))); // the yolk shining through
        return brighten([60, 130, 40], 1.1 - 0.4 * d);                          // the shell
      }
      // The membrane, with veins: thin dark ridges where a wavy pattern crosses zero.
      const vein = Math.abs(Math.sin(x * 0.45 + 3 * Math.sin(y * 0.21)) + Math.sin(y * 0.38 + 2 * Math.sin(x * 0.17)));
      if (dead) return brighten([50, 30, 26], 0.4 + 0.4 * noise(x, y, 221));
      if (vein < 0.12) return [60, 10, 24];
      return brighten(MEMBRANE, 0.75 + 0.35 * noise(x >> 1, y >> 1, 222) + 0.08 * pulse);
    }
    if (r < port + 3) return dead ? [30, 30, 32] : brighten(STEEL, r < port + 1 ? 0.5 : 1.25); // the viewport's rim
    // Ooze running down out of the cracks, once it's damaged.
    if (!dead && damage > 0 && y > cy && noise(x, 0, 223) < 0.12 * damage && y < cy + port + 10 * noise(x, 1, 223) + 4) {
      return brighten(BIO_GREEN, 0.6 + 0.3 * noise(x, y, 224));
    }
    // Growth creeping out over the steel round the rim.
    if (r < port + 3 + 7 * noise(Math.floor((a + Math.PI) * 6), 0, 225)) {
      return dead ? [24, 20, 18] : brighten(MEMBRANE, 0.6 + 0.2 * noise(x, y, 226));
    }
    if (x < 2 || y < 2 || x >= 62 || y >= 62) return brighten(DARK_STEEL, 0.8);   // frame
    const plate = brighten(STEEL, 0.75 + 0.12 * noise(x, y, 227));
    return dead ? mix(plate, [10, 8, 8], 0.6) : plate;
  });
}

// THE HQ ------------------------------------------------------------------------
// The company's headquarters, where the infection got out of the atrium
// garden and into the air conditioning. Corporate offices slowly turning into
// a greenhouse: beige walls and wood panelling with ivy creeping up and down
// them, carpet tiles going to moss, roots cracking through, daylight falling
// through the atrium's skylights. Levels with theme 'hq' use its floor and
// ceiling; its walls are their own cells ('o', 'v').

const LEAF = [64, 112, 44];
const LEAF_DARK = [34, 64, 28];
const ROOT = [86, 62, 40];
const OFFICE_PAINT = [178, 170, 150];
const OFFICE_WOOD = [112, 76, 48];

// LEAVES, scattered over a texture: one leaf (maybe) in each 8x8 square, at a
// random spot and angle, so they overlap like real foliage. `density(y)` is
// the chance of a leaf at height y, so ivy can thin out up a wall. The
// squares wrap round the edges, so the texture still tiles. Returns the
// leaf's colour, or null where there's no leaf.
function leafAt(x, y, seed, density) {
  const gx = x >> 3, gy = y >> 3;
  let best = null, bestTop = -1;
  for (let j = -1; j <= 1; j++) {
    for (let i = -1; i <= 1; i++) {
      const cx = (gx + i + 8) % 8, cy = (gy + j + 8) % 8; // this square, wrapped
      const lx = cx * 8 + 1 + 6 * noise(cx, cy, seed + 1);
      const ly = cy * 8 + 1 + 6 * noise(cx, cy, seed + 2);
      if (noise(cx, cy, seed) >= density(ly)) continue;
      const dx = ((x + 0.5 - lx + 96) % 64) - 32, dy = ((y + 0.5 - ly + 96) % 64) - 32; // the shortest way, round the wrap
      const a = noise(cx, cy, seed + 3) * Math.PI * 2;
      const len = 4.5 + 2 * noise(cx, cy, seed + 4);
      const u = (dx * Math.cos(a) + dy * Math.sin(a)) / len;        // along the leaf
      const v = (-dx * Math.sin(a) + dy * Math.cos(a)) / (len * 0.45); // across it
      const r = u * u + v * v;
      if (r >= 1) continue;
      const top = noise(cx, cy, seed + 5); // which leaf lies on top where two overlap
      if (top < bestTop) continue;
      bestTop = top;
      const tint = mix(LEAF, [110, 140, 50], noise(cx, cy, seed + 6) * 0.5); // some younger and yellower
      best = Math.abs(v) < 0.18 && Math.abs(u) < 0.8 ? brighten(tint, 1.25)  // the midrib
        : brighten(tint, 0.7 + 0.45 * (1 - r) + 0.15 * u);                  // lit towards its tip
    }
  }
  return best;
}

// Office wall: beige paint over wood panelling, with a dado rail between,
// and ivy creeping up from the floor and down from the ceiling.
function makeOfficeWall() {
  const ivy = (y) => y > 40 ? 0.75 * (y - 40) / 23 : y < 14 ? 0.6 * (14 - y) / 14 : 0;
  return makeTexture(OFFICE_PAINT, (x, y) => {
    const leaf = leafAt(x, y, 300, ivy);
    if (leaf) return leaf;
    // A stem or two winding up through it.
    const stem = 9 + 44 * noise(x >> 5, 0, 301) + 2.5 * Math.sin(y * 0.3 + x);
    if (Math.abs(x + 0.5 - stem) < 0.7 && (y > 46 || y < 8)) return LEAF_DARK;
    if (y >= 62) return brighten(OFFICE_WOOD, 0.4);                                // skirting
    if (y >= 38 && y < 41) return brighten(OFFICE_WOOD, y === 38 ? 1.35 : 0.85);   // dado rail
    if (y >= 41) {                                                                  // panelling
      const px = x % 16;
      if (px === 0) return brighten(OFFICE_WOOD, 0.5);
      if (px === 1 || y === 41) return brighten(OFFICE_WOOD, 1.2);
      return brighten(OFFICE_WOOD, 0.8 + 0.12 * noise(x >> 1, y >> 3, 302) + 0.06 * Math.sin(x * 1.7 + y * 0.2)); // grain
    }
    // Paint, with a faint stripe in the wallpaper and damp running down it.
    const f = (x % 8 === 0 ? 0.94 : 1) * (0.92 + 0.06 * noise(x, y, 303));
    const damp = noise(x >> 1, 0, 304) > 0.82 ? 0.35 * (1 - y / 38) * noise(x >> 1, y >> 3, 305) : 0;
    return mix(brighten(OFFICE_PAINT, f), [120, 128, 90], damp);
  });
}

// Overgrown: a wall (or one of the atrium's planters) gone under the leaves
// entirely, two layers of them, with dark gaps and the odd pale flower.
function makeOvergrownWall() {
  return makeTexture(LEAF, (x, y) => {
    const n = noise(x >> 1, y >> 1, 310);
    if (n < 0.025) return brighten([230, 200, 210], 0.9 + 0.2 * noise(x, y, 311)); // a flower
    return leafAt(x, y, 312, () => 0.9) || brighten(leafAt(x, y, 316, () => 0.95) || LEAF_DARK, 0.6);
  });
}

// Carpet tiles, the pile laid alternate ways, with moss spreading across them
// and roots cracking through.
function makeHqFloor() {
  const carpet = [84, 90, 102];
  return makeTexture(carpet, (x, y) => {
    const root = 20 + 6 * Math.sin(x * Math.PI * 2 / 64 * 2) + 3 * Math.sin(x * Math.PI * 2 / 64 * 5);
    if (Math.abs(y + 0.5 - root) < 1.4 - 0.6 * noise(x >> 2, 0, 320)) return brighten(ROOT, 0.8 + 0.3 * noise(x, y, 321));
    const moss = 0.6 * noise(x >> 3, y >> 3, 322) + 0.4 * noise(x >> 1, y >> 1, 323);
    if (moss > 0.66) return brighten([66, 104, 42], 0.75 + 0.4 * noise(x, y, 324));
    if (x % 32 === 0 || y % 32 === 0) return brighten(carpet, 0.6);                  // seams
    const along = ((x >> 5) + (y >> 5)) % 2 === 0 ? x : y;                           // the pile's direction
    const f = (along % 3 === 0 ? 0.9 : 1) * (0.88 + 0.1 * noise(x, y, 325));
    return mix(brighten(carpet, f), [70, 90, 50], moss > 0.55 ? 0.35 : 0);           // the moss's green creeping in
  });
}

// Ceiling tiles, warm off-white. Where there's a light, a SKYLIGHT in the
// middle: daylight in `glow`'s colour through panes and a cross of mullions.
// With no light (null), just the tiles. Ivy trails from the T-bars.
function makeHqCeiling(glow) {
  const tile = [180, 176, 160];
  return makeTexture(tile, (x, y) => {
    if (glow && x >= 14 && x < 50 && y >= 14 && y < 50) {
      if (x === 14 || x === 49 || y === 14 || y === 49 || x === 31 || x === 32 || y === 31 || y === 32) return [60, 62, 58];
      return glowing(brighten(glow, 0.92 + 0.08 * noise(x >> 2, y >> 2, 331)));
    }
    const leaf = leafAt(x, y, 332, (ly) => (ly < 12 || ly > 52) ? 0.35 : 0);
    if (leaf) return brighten(leaf, 0.8);
    if (x % 32 < 2 || y % 32 < 2) return brighten([130, 126, 112], x % 32 === 0 || y % 32 === 0 ? 0.7 : 1); // T-bars
    if (noise(x >> 1, y >> 1, 333) < 0.12) return brighten(tile, 0.8);                                     // the fissured pattern
    return mix(brighten(tile, 0.9 + 0.08 * noise(x, y, 334)), [130, 120, 80], noise(x >> 4, y >> 4, 335) < 0.25 ? 0.3 : 0); // water stains
  });
}

// THE MOTHER PLANT (core.js, levels whose objective is 'motherplant'): where
// the infection began. A wall of woven roots, with a great fleshy BLOOM at its
// heart, gold at the centre, that pulses. Somewhere in it is the chief
// executive: a red tie hangs from under the bloom, and a hand reaches out of
// the roots. `damage` 0-2 wilts the petals and splits it, bleeding sap;
// `pulse` 0-3 is how bright its heart is this moment; `dead`, burnt out.
const BLOOM = [214, 104, 120];
const BLOOM_HEART = [255, 214, 90];
const SAP = [220, 170, 40];

function makeMotherPlant(damage, pulse, dead) {
  const cx = 32, cy = 26;
  const char = (c) => mix(c, [14, 10, 8], 0.8);
  return makeTexture(ROOT, (x, y) => {
    const dx = x + 0.5 - cx, dy = y + 0.5 - cy;
    const r = Math.hypot(dx, dy), a = Math.atan2(dy, dx);
    // The bloom: five petals round a heart.
    const petal = 12 + 4 * Math.cos(5 * a + 0.4);
    if (r < 5.5) {
      if (dead) return noise(x, y, 340) < 0.15 ? glowing([255, 120, 30]) : [30, 24, 18]; // embers
      return glowing(brighten(BLOOM_HEART, 0.45 + 0.17 * pulse + 0.3 * (1 - r / 5.5)));
    }
    if (r < petal) {
      const t = (r - 5.5) / (petal - 5.5);
      // Splits in the petals with damage, and sap welling out of them.
      if (damage > 0 && Math.abs(Math.sin(a * 5 + 1.3)) < 0.06 * damage) return dead ? [10, 8, 6] : brighten(SAP, 0.9);
      const wilt = damage * 0.28;
      let c = mix(brighten(BLOOM, 1.15 - 0.45 * t), [110, 70, 40], wilt);
      if (Math.abs(Math.sin(a * 5 + 0.4)) < 0.1) c = brighten(c, 0.75);                  // the groove down each petal
      if (dead) return char(c);
      return t < 0.3 ? glowing(brighten(c, 0.85 + 0.08 * pulse)) : c;                    // the inner petals glow
    }
    // The tie, hanging out from under the bloom, and the collar above it.
    if (y >= 38 && y < 41 && Math.abs(dx) < 5 - (y - 38)) return dead ? [40, 38, 34] : [214, 210, 196];
    if (y >= 41 && y < 58) {
      const half = y < 43 ? 1.4 : 1.4 + (y - 43) * 0.12;
      if (Math.abs(dx) < half) return dead ? [34, 14, 12] : brighten([150, 28, 30], Math.abs(dx) < 0.6 ? 1.2 : 0.85);
    }
    // A hand reaching out of the roots, bottom left.
    const palm = Math.hypot((x + 0.5 - 13) / 3.6, (y + 0.5 - 52) / 3);
    let hand = palm < 1;
    for (const [fx, fy] of [[-3, -5], [-1, -6], [1, -6], [3, -5]]) {
      if (segmentDistance(x + 0.5, y + 0.5, 13 + fx * 0.6, 50, 13 + fx, 52 + fy) < 0.8) hand = true;
    }
    if (segmentDistance(x + 0.5, y + 0.5, 16, 53, 20, 51) < 1) hand = true; // thumb
    if (hand) return dead ? [40, 34, 30] : brighten([168, 170, 148], 0.85 + 0.2 * noise(x, y, 341));
    // Sap running down from the splits, once it's hurt.
    if (!dead && damage > 0 && y > cy && noise(x, 0, 342) < 0.1 * damage && y < 40 + 18 * noise(x, 1, 342)) return brighten(SAP, 0.7);
    // The roots, woven: two wavy sets of strands crossing.
    const w1 = Math.abs(Math.sin(x * 0.42 + 2.2 * Math.sin(y * 0.14)));
    const w2 = Math.abs(Math.sin(y * 0.36 + 2.0 * Math.sin(x * 0.12 + 1)));
    let c;
    if (w1 < 0.3) c = brighten(ROOT, 1.15 - w1);
    else if (w2 < 0.3) c = brighten(ROOT, 0.95 - w2);
    else c = noise(x >> 2, y >> 2, 343) < 0.35 ? brighten(LEAF_DARK, 0.9) : [26, 20, 14]; // leaves, and the dark between
    // Glowing seed-sacs dotted about the roots: one (maybe) in each 8x8 square, round, somewhere in it.
    const sx = (x >> 3) * 8 + 2 + 4 * noise(x >> 3, y >> 3, 345), sy = (y >> 3) * 8 + 2 + 4 * noise(x >> 3, y >> 3, 346);
    if (!dead && noise(x >> 3, y >> 3, 344) < 0.3 && Math.hypot(x + 0.5 - sx, y + 0.5 - sy) < 1.8 && Math.hypot(sx - cx, sy - cy) > 17) {
      return glowing(brighten(BLOOM_HEART, 0.4 + 0.12 * pulse));
    }
    return dead ? char(c) : c;
  });
}

// OFFICE FURNITURE (sprites.js). A planter, the corporate kind, with a ficus
// that's grown wild; and a desk with its green-screen terminal still on.
function makePottedPlant() {
  const pot = [196, 194, 186];
  return makeTexture(LEAF, (x, y) => {
    const dx = x + 0.5 - 32;
    if (y >= 46) {
      if (Math.abs(dx) > 10 - (y - 46) * 0.12) return null;
      if (y < 48) return brighten(pot, y === 46 ? 1.3 : 0.6);                       // the rim
      return brighten(pot, roundShade(dx / 10) * (0.9 + 0.08 * noise(x, y, 350)));
    }
    if (Math.abs(dx + 1.5 * Math.sin(y * 0.2)) < 1.4 && y > 24) return brighten(ROOT, 0.9); // the trunk
    const crown = Math.hypot(dx / 17, (y + 0.5 - 24) / 19);
    if (crown >= 1) return null;
    return leafAt(x, y, 352, () => 0.95) || (crown < 0.75 ? brighten(LEAF_DARK, 0.7) : null);
  });
}

function makeDesk() {
  const laminate = [150, 122, 84], beige = [184, 176, 150];
  return makeTexture(laminate, (x, y) => {
    const dx = x + 0.5 - 32;
    // The terminal on it: a beige box and its green screen.
    if (dx > -14 && dx < 4 && y >= 19 && y < 37) {
      if (dx > -12 && dx < 2 && y >= 21 && y < 33) {
        const text = (y - 22) % 3 === 0 && dx < -4 + 8 * noise(y, 0, 353) && dx > -11;
        return glowing(text ? [120, 255, 140] : [20, 70, 36]);
      }
      return brighten(beige, y === 19 ? 1.25 : 0.85 + 0.1 * noise(x, y, 354));
    }
    if (dx > -8 && dx < -2 && y >= 37 && y < 40) return brighten(beige, 0.7);     // its stand
    if (Math.abs(dx) > 26) return null;
    if (y >= 40 && y < 43) return brighten(laminate, y === 40 ? 1.3 : 1);            // the desktop
    if (y >= 43 && y < 62) {
      if (Math.abs(dx) > 23) return brighten(laminate, 0.55);                        // the ends
      if (y < 56) return brighten(laminate, 0.42 + 0.06 * noise(x, y, 355));         // the modesty panel, in shadow
    }
    // Ivy up one leg.
    if (y >= 43 && dx > 20) { const leaf = leafAt(x, y, 356, () => 0.8); if (leaf) return leaf; }
    return null;
  });
}

// THE PLAYER'S GUN ----------------------------------------------------------------
// A chunky pulse gun seen from behind, with three coils round the barrel.
// It isn't drawn in the world: hud.js stamps it onto the bottom of the screen
// at 2x size. `flash` draws it firing. The coils show the FIRE MODE
// (weapons.js): `lit` of them glow, counting from the body: one is single
// shot, two burst, three automatic. Only the count means anything; the coil
// colour is kept free to mean something else later (an ammo type, say).
const COIL_COLOUR = [90, 230, 255];
function makeGun(flash, lit) {
  return makeTexture(DARK_STEEL, (x, y) => {
    const dx = x + 0.5 - 32;
    if (flash && y >= 0 && y < 14) {
      // A spiky starburst: its radius varies with the angle around the centre.
      const fy = y + 0.5 - 7;
      const r = 4.5 + 3.5 * Math.abs(Math.cos(4 * Math.atan2(fy, dx)));
      const d = Math.hypot(dx, fy);
      if (d <= r * 0.5) return [230, 255, 255];
      if (d <= r) return [90, 210, 255];
    }
    // Still a chunky block of pixels, but shaped rather than stacked boxes:
    // the barrel tapers to a flared muzzle, sloping shoulders join it to the
    // body, and the body's corners are rounded off and it widens towards you.
    const ax = Math.abs(dx);
    if (y >= 10 && y < 13) {                                              // muzzle brake: a flared lip
      if (ax >= 3.5) return null;
      if (y === 10 && ax < 1.5) return [16, 16, 18];                      // the bore, seen from behind
      if (y === 11 && ax >= 2.5) return [16, 16, 18];                     // brake ports either side
      return brighten(DARK_STEEL, y === 10 ? 1.6 : 1.2);
      return null;
    }
    if (y >= 13 && y < 27) {                                              // barrel shroud, tapering to the front
      const halfW = 3 + (y - 13) * 0.15;
      if (ax >= halfW) return null;
      const n = [24, 20, 16].indexOf(y);                                  // coil 0 nearest the body
      if (n !== -1 && n < lit) return glowing(COIL_COLOUR);               // a lit coil
      if (n !== -1) return [30, 34, 40];                                  // an unlit one
      if (y < 15) return brighten(DARK_STEEL, roundShade(dx / halfW));    // bare barrel tip
      return brighten(DARK_STEEL, roundShade(dx / halfW) * 1.3);
    }
    if (y >= 27 && y < 31) {                                              // shoulders: sloping out to the body
      const halfW = 5.5 + (y - 27) * 1.2;
      if (ax >= halfW) return null;
      if (y === 27 && ax < 1) return brighten(DARK_STEEL, 2);             // front sight post
      return brighten(DARK_STEEL, (1.9 - (y - 27) * 0.1) * roundShade(dx / halfW));
    }
    if (y >= 31 && y < 47) {                                              // body, widening towards you
      const halfW = 10 + (y - 31) * 0.15;
      if (ax > halfW) return null;
      if (y < 33 && ax > halfW - 2) return null;                          // rounded top corners
      if (y === 31 && ax >= 2 && ax < 3) return brighten(DARK_STEEL, 2);  // rear sight notch
      if (ax > halfW - 3 && y % 4 === 0) return [16, 16, 18];             // side vents
      if (y >= 37 && y < 43 && ax < 3.5) return [10, 8, 8];               // ammo counter window (hud.js draws the digits)
      if (y >= 36 && y < 44 && ax < 4.5) return [24, 24, 28];             // its bezel
      return brighten([64, 68, 78], roundShade(dx / halfW) * 1.1);
    }
    if (y >= 47) return gunHand(x, y, dx);
    return null;
  });
}

// The black-gloved hand holding every gun, from row 47 down.
function gunHand(x, y, dx) {
  const halfW = 9 + (y - 47) * 0.25;
  if (Math.abs(dx) > halfW) return null;
  let f = 0.9 + 0.15 * noise(x, y, 45) - 0.3 * Math.abs(dx / halfW);
  if ((y - 47) % 5 === 0 && dx > -4) f *= 0.6; // knuckle creases
  return brighten([58, 54, 52], f);
}

// A fire-mode upgrade module lying on the floor: a small steel cartridge with
// `stripes` glowing stripes, matching the number of coils it lights on your gun.
function makeUpgradeModule(stripes) {
  return makeTexture(COIL_COLOUR, (x, y) => {
    if (y < 50 || y >= 62 || x < 22 || x >= 42) return null;
    if (y === 50 || y === 61 || x === 22 || x === 41) return DARK_STEEL;   // casing edge
    const band = Math.floor((x - 25) / 5);                                 // three stripe slots
    if (y >= 53 && y < 59 && (x - 25) % 5 < 3 && band >= 0 && band < 3) {
      return band < stripes ? glowing(COIL_COLOUR) : [30, 34, 40];
    }
    return brighten(STEEL, 0.8 + 0.2 * noise(x, y, 50));
  });
}

// PICKUPS ---------------------------------------------------------------------
// Small things lying on the floor, so drawn in the bottom rows.

// An olive ammo crate with a hazard stripe.
function makeAmmoBox() {
  const olive = [95, 105, 60];
  return makeTexture(olive, (x, y) => {
    const dx = x + 0.5 - 32;
    if (y < 48 || Math.abs(dx) > 12) return null;
    if (y < 51) return brighten(olive, 1.3);                          // lid, lit from above
    if (Math.abs(dx) > 11 || y === 51) return brighten(olive, 0.55);  // edges
    if (y >= 55 && y < 58) return hazard(x, y, false);
    return brighten(olive, 0.9 + 0.15 * noise(x, y, 18));
  });
}

// The lab's AMMO CRATE: a big white supply case with a green band and a
// carrying handle. The lab's creatures drop nothing, so its ammo comes in these.
function makeAmmoCrate() {
  const white = [190, 196, 188];
  return makeTexture(white, (x, y) => {
    const dx = x + 0.5 - 32;
    if (y >= 38 && y < 41 && Math.abs(dx) < 6 && Math.abs(dx) > 3.5) return brighten(DARK_STEEL, 1.2); // handle
    if (y === 38 && Math.abs(dx) < 6) return brighten(DARK_STEEL, 1.2);
    if (y < 41 || Math.abs(dx) > 17) return null;
    if (y < 44) return brighten(white, 1.2);                              // lid, lit from above
    if (Math.abs(dx) > 16 || y === 44 || y === 62) return brighten(white, 0.5); // edges
    if (y >= 50 && y < 55) return brighten([70, 160, 60], 0.9 + 0.1 * noise(x, y, 19)); // the green band
    if ((Math.abs(dx) === 12.5 || Math.abs(dx) === 13.5) && y > 45 && y < 61) return brighten(white, 0.7); // ribs
    return brighten(white, 0.85 + 0.12 * noise(x, y, 20));
  });
}

// The DEMOLITION CHARGE (charge.js): a slab of grey-khaki plastic explosive,
// bound with two bands of tape, with a little black detonator on top and
// its red arming lamp. `top` is the detonator's top row: low for the one
// lying on the floor as a pickup, mid-height for one stuck to the core.
// `lit`: the lamp blinks once it's set, so it comes in lit and unlit.
function makeCharge(top, lit) {
  const putty = [168, 160, 122];
  const TAPE = [64, 66, 70];
  return makeTexture(putty, (x, y) => {
    const dx = x + 0.5 - 32;
    const row = y - top;
    if (row < 0 || row >= 14) return null;
    if (row < 4) {                                                   // the detonator
      if (Math.abs(dx) > 4) return (dx < -4 && dx > -7 && row === 3) ? [200, 40, 30] : null; // a red wire into the slab
      if (row >= 1 && row <= 2 && dx > 0.5 && dx < 2.5) return lit ? glowing([255, 40, 30]) : [90, 20, 18]; // the lamp
      return brighten([40, 42, 46], row === 0 ? 1.4 : 1);
    }
    if (Math.abs(dx) > 10) return null;                               // the slab
    if (Math.abs(dx) > 9 || row === 13) return brighten(putty, 0.55); // its edges
    if (Math.abs(Math.abs(dx) - 5) < 1.5) return brighten(TAPE, 0.9 + 0.2 * noise(x, y, 23)); // tape
    if (row === 4) return brighten(putty, 1.25);                      // top edge, lit from above
    return brighten(putty, 0.85 + 0.15 * noise(x, y, 22));
  });
}

// An energy cell, dropped by a destroyed robot: a small canister with a glowing band.
function makeClip() {
  return makeTexture(DARK_STEEL, (x, y) => {
    const dx = x + 0.5 - 32;
    if (y < 50 || Math.abs(dx) > 4) return null;
    if (y < 52) return brighten(STEEL, 1.3);                           // cap
    if (y >= 55 && y < 58) return glowing([90, 230, 255]);
    return brighten(DARK_STEEL, roundShade(dx / 4) * 1.3);
  });
}

// A suit repair kit: a squat steel canister of repair paste with a nozzle,
// a hazard band, and a green light that says it's charged. Small and on the
// floor, so it's drawn in the bottom rows.
function makeRepairKit() {
  const steel = [150, 156, 164];
  return makeTexture(steel, (x, y) => {
    const dx = x + 0.5 - 32;
    const ax = Math.abs(dx);
    if (y >= 43 && y < 47 && ax < 2) return brighten(DARK_STEEL, y === 43 ? 1.6 : 1.1);   // nozzle
    if (y < 47 || y >= 63 || ax >= 9) return null;
    if (y < 49) return brighten(DARK_STEEL, 1.3);                                         // cap
    if (y >= 50 && y < 52 && ax < 2) return glowing([90, 255, 120]);                      // charged light
    if (y >= 54 && y < 57) return hazard(x, y, false);                                    // hazard band
    if (y >= 61) return brighten(DARK_STEEL, 1.1);                                        // base ring
    return brighten(steel, roundShade(dx / 9) * (0.9 + 0.1 * noise(x, y, 19)));
  });
}

// A keycard lying on the floor. It glows, so you can spot it in the dark.
function makeKeycard(colour) {
  return makeTexture(colour, (x, y) => {
    const dx = x + 0.5 - 32;
    if (y < 55 || y >= 62 || Math.abs(dx) > 7) return null;
    if (y === 57) return glowing([235, 235, 235]);              // magnetic stripe
    if (dx > 3 && y > 58) return glowing([230, 200, 90]);       // chip
    return glowing(brighten(colour, y === 55 ? 1.3 : 1));
  });
}

const KEYCARD_TEXTURES = {};
for (const colour in KEY_COLOURS) KEYCARD_TEXTURES[colour] = makeKeycard(KEY_COLOURS[colour]);
// The LIFT KEY (core.js, levels whose objective is 'liftkey'): a gold card.
const LIFT_KEY_COLOUR = [240, 190, 50];
const LIFT_KEY_TEXTURE = makeKeycard(LIFT_KEY_COLOUR);

const AMMO_BOX_TEXTURE = makeAmmoBox();
const AMMO_CRATE_TEXTURE = makeAmmoCrate();
const CHARGE_TEXTURE = makeCharge(49, false);                          // lying on the floor
const CHARGE_SET_TEXTURES = { lit: makeCharge(26, true), unlit: makeCharge(26, false) }; // stuck to the core
const CLIP_TEXTURE = makeClip();
const REPAIR_KIT_TEXTURE = makeRepairKit();

const CAMERA_TEXTURES = { watching: makeCamera('watching'), offline: makeCamera('offline'), destroyed: makeCamera('destroyed') };
const BEAM_TEXTURE = makeBeam();
const TERMINAL_TEXTURES = { armed: makeTerminal(false), safe: makeTerminal(true) };
// CORE_TEXTURES[damage][pulse], and the wreck.
const CORE_TEXTURES = [0, 1, 2].map((damage) => [0, 1, 2, 3].map((pulse) => makeCore(damage, pulse, false)));
const CORE_DEAD_TEXTURE = makeCore(2, 0, true);
// The lab's breeding chamber, the same way: CHAMBER_TEXTURES[damage][pulse], and the wreck.
const CHAMBER_TEXTURES = [0, 1, 2].map((damage) => [0, 1, 2, 3].map((pulse) => makeChamber(damage, pulse, false)));
const CHAMBER_DEAD_TEXTURE = makeChamber(2, 0, true);
// The HQ's mother plant, the same way: MOTHER_PLANT_TEXTURES[damage][pulse], and the wreck.
const MOTHER_PLANT_TEXTURES = [0, 1, 2].map((damage) => [0, 1, 2, 3].map((pulse) => makeMotherPlant(damage, pulse, false)));
const MOTHER_PLANT_DEAD_TEXTURE = makeMotherPlant(2, 0, true);
const LIFT_TEXTURES = { locked: makeLift(false), open: makeLift(true) };
// The gun in each fire mode, [normal, firing], and the upgrade modules (weapons.js).
// GUN_TEXTURES[n] is the gun with n coils lit: [normal, firing].
const GUN_TEXTURES = [1, 2, 3].map((lit) => [makeGun(false, lit), makeGun(true, lit)]);
GUN_TEXTURES.unshift(null); // so GUN_TEXTURES[1] is one coil, not GUN_TEXTURES[0]
const BURST_MODULE_TEXTURE = makeUpgradeModule(2);
const AUTO_MODULE_TEXTURE = makeUpgradeModule(3);

const GLASS_TEXTURES = { intact: makeGlass('intact'), cracked: makeGlass('cracked'), shattered: makeGlass('shattered') };
const GRATE_TEXTURE = makeGrate();
const GLASS_BURST_FRAMES = [0, 1, 2, 3].map(makeGlassBurst);

const STEAM_BURST_FRAMES = [];
const STEAM_SPUTTER_FRAMES = [];
for (let f = 0; f < STEAM_FRAMES; f++) {
  STEAM_BURST_FRAMES.push(makeSteam(f, false, THEME.ventGas));
  STEAM_SPUTTER_FRAMES.push(makeSteam(f, true, THEME.ventGas));
}

const DRUM_TEXTURE = makeDrum();
const DRUM_WRECK_TEXTURE = makeDrumWreck();
const FIREBALL_FRAMES = [0, 1, 2, 3, 4].map(makeFireball);
const STRUT_TEXTURE = makeStrut();
const LAMP_TEXTURE = makeCagedLamp();
const POTTED_PLANT_TEXTURE = makePottedPlant();
const DESK_TEXTURE = makeDesk();

// The floor and ceiling come with the level's theme (map.js: THEMES): the
// ceiling three times, with its lights on, off, and red for an alarm.
const FLOOR_TEXTURE = THEME.floor();
const CEILING_TEXTURE = THEME.ceiling(THEME.ceilingGlow);
const CEILING_DARK_TEXTURE = THEME.ceiling(null);
const CEILING_ALARM_TEXTURE = THEME.ceiling([255, 40, 30]);

// ANIMATED WALLS. The computer bank exists as several frames; wallTexture
// picks one from animTime, which the main loop advances every frame. The
// renderer doesn't know or care: it just gets a different texture each time.
const COMPUTER_FRAMES = [0, 1, 2, 3].map(makeComputerBank);
const ANIMATED_WALLS = { 3: COMPUTER_FRAMES };
const ANIMATION_FPS = 3;
let animTime = 0; // seconds since the game started

// Map cell value -> texture. Every non-zero number used in MAP needs an entry.
// (Animated walls list their first frame here, for the map check and debug map.)
const TEXTURES = {
  1: makeSteelPlates(),
  2: makeBulkhead(),
  3: COMPUTER_FRAMES[0],
  4: makePipes(),
  5: TERMINAL_TEXTURES.armed, // security terminal (security.js shows armed or safe)
  [GLASS_CELL]: GLASS_TEXTURES.intact, // panels.js shows intact, cracked or shattered
  [GRATE_CELL]: GRATE_TEXTURE,
  [TANK_GLASS_CELL]: GLASS_TEXTURES.intact,
  [CORE_CELL]: CORE_TEXTURES[0][0], // core.js shows its damage, pulse, or wreck
  [LIFT_CELL]: LIFT_TEXTURES.locked, // core.js shows locked or open
  [DOOR_CELL]: makeBlastDoor(null),
  [LAB_TILE_CELL]: makeLabTiles(),
  [LAB_CABINET_CELL]: makeLabCabinet(),
  [OFFICE_WALL_CELL]: makeOfficeWall(),
  [OVERGROWN_CELL]: makeOvergrownWall(),
};

function wallTexture(cell) {
  const frames = ANIMATED_WALLS[cell];
  return frames ? frames[Math.floor(animTime * ANIMATION_FPS) % frames.length] : TEXTURES[cell];
}

// Doors look different depending on their lock: one texture per key colour.
const LOCKED_DOOR_TEXTURES = {};
for (const colour in KEY_COLOURS) LOCKED_DOOR_TEXTURES[colour] = makeBlastDoor(colour);

function doorTexture(door) {
  return door.lock ? LOCKED_DOOR_TEXTURES[door.lock] : TEXTURES[DOOR_CELL];
}
